                return P11_RPC_VALUE_MECHANISM_TYPE_ARRAY;
        case CKA_START_DATE:
        case CKA_END_DATE:
                return P11_RPC_VALUE_DATE;
        default:
                p11_debug ("cannot determine the type of attribute value for %lu; assuming byte array",
                           type);
                /* fallthrough */
        case CKA_LABEL:
