static void
test_new_free (void)
{
        p11_buffer *buf;

        buf = p11_rpc_buffer_new (0);

        assert_ptr_not_null (buf->data);
        assert_num_eq (0, buf->len);
        assert_num_eq (0, buf->flags);
        assert (buf->size == 0);
        assert_ptr_not_null (buf->ffree);
        assert_ptr_not_null (buf->frealloc);

        p11_rpc_buffer_free (buf);
}

